            if t == "--":
                i += 1
                break
            if t in ("--cwd", "--timeout", "--env", "--tail") and i + 1 < len(rest):
                v = rest[i + 1]
                if t == "--cwd":
                    a.cwd = v
                elif t == "--timeout":
                    a.timeout = int(v)
                elif t == "--tail":
                    a.tail = int(v)
                else:
                    a.env.append(v)
                i += 2
                continue
            if t.startswith("--cwd=") or t.startswith("--timeout=") or t.startswith("--env=") or t.startswith("--tail="):
                k, v = t[2:].split("=", 1)
                if k == "cwd":
                    a.cwd = v
                elif k == "timeout":
                    a.timeout = int(v)
                elif k == "tail":
                    a.tail = int(v)
                else:
                    a.env.append(v)
                i += 1
                continue
            if t == "--json":
                a.json = True
                i += 1
                continue
            if a.id is None and not t.startswith("-"):
                a.id = t
                i += 1
                continue
            break  # first command token
